//! The stock API's docs, from our own bindings: [`STOCK_API`] is generated by `build.rs`
//! ([`crate::stock_extract`]) from `wrathplus-ui/src/script`, each registered function with the
//! comment above its registration (our words, written from the 12340 decompile), its `file:line`,
//! the arity census's note when it has one, and the registration's text. A binding without a
//! comment says so; nothing is invented.

use crate::search::Entry;

/// One binding: name, `file:line`, the comment above it, the census's arity note, its source.
pub(crate) type Row = (
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
);

include!(concat!(env!("OUT_DIR"), "/stock_api.rs"));

/// What a binding with no comment above it says.
pub(crate) const UNDOCUMENTED: &str = "No comment above its binding: read the source at `at`.";

/// The row for `name` (exact, as Lua names are case-sensitive).
fn row(name: &str) -> Option<&'static Row> {
    STOCK_API
        .binary_search_by(|r| r.0.cmp(name))
        .ok()
        .map(|i| &STOCK_API[i])
}

/// A stock function's entry, kind `api`: its doc (with the census's arity note), where we bind it
/// and the binding's source; `None` for a global we have no binding for (Lua's own, or one the
/// stock UI or an addon defined).
pub(crate) fn entry(name: &str) -> Option<Entry> {
    let (name, at, doc, note, source) = row(name)?;
    let mut text = if doc.is_empty() {
        UNDOCUMENTED.to_string()
    } else {
        (*doc).to_string()
    };
    if !note.is_empty() {
        text.push_str(&format!(" Arity (census): {note}."));
    }
    Some(Entry {
        kind: "api",
        name: (*name).to_string(),
        signature: String::new(),
        doc: text,
        at: (*at).to_string(),
        source: Some((*source).to_string()),
    })
}

/// A bare `api` entry: a global we have no binding text for.
pub(crate) fn bare(name: String) -> Entry {
    Entry {
        kind: "api",
        name,
        signature: String::new(),
        doc: String::new(),
        at: String::new(),
        source: None,
    }
}

